sys_variable_value.value:
(function execute(inputs, outputs) {
    var inputName = (inputs.company || "").trim();
    
    // Initial Input Debug
    gs.info("[CompanyLookup Debug] --- START TRACE ---");
    gs.info("[CompanyLookup Debug] Input Received: >>>" + inputName + "<<< (Length: " + inputName.length + ")");

    if (!inputName) {
        gs.info("[CompanyLookup Debug] Check: 'inputName exists' -> FALSE. Exiting.");
        outputs.matched_name = "No input provided";
        outputs.matched_name_ai = "No input provided";
        outputs.definitive_name = "";
        outputs.name_agreed = false;
        return;
    }

    var helper = new global.FindClosestCompany(); 
    var aiHelper = new x_1815796_itsmgr_0.AiBotHelper();

    // --- STEP 1: EXACT MATCH CHECK ---
    gs.info("[CompanyLookup Debug] Step 1: Querying core_company for Name/Alias match...");
    var exactMatchGr = new GlideRecord('core_company');
    exactMatchGr.addActiveQuery();
    var qc = exactMatchGr.addQuery('name', inputName);
    qc.addOrCondition('u_alias', 'CONTAINS', inputName);
    exactMatchGr.query();

    var hasExactMatch = exactMatchGr.next();
    gs.info("[CompanyLookup Debug] Check: 'Exact Match Found' -> " + hasExactMatch);

    if (hasExactMatch) {
        var dbName = exactMatchGr.getValue('name');
        gs.info("[CompanyLookup Debug] Exact Match Value: >>>" + dbName + "<<<");
        outputs.matched_name = dbName;
        outputs.matched_name_ai = dbName;
        outputs.definitive_name = dbName;
        outputs.name_agreed = true;
        return; 
    }

    // --- STEP 2: FUZZY & AI SEARCH ---
    gs.info("[CompanyLookup Debug] Step 2: Initiating Parallel Searches.");
    
    var result_by_code = helper.findCompanyByCode(inputName);
    gs.info("[CompanyLookup Debug] Fuzzy Helper Result: >>>" + result_by_code + "<<< (Length: " + (result_by_code ? result_by_code.length : 0) + ")");

    var raw_AI_response = aiHelper.findClosestCompany(inputName);
    
    // SPECIAL: Unicode/Hex Log for Encoding issues
    if (raw_AI_response) {
        var hexDump = "";
        for (var i = 0; i < raw_AI_response.length; i++) {
            hexDump += raw_AI_response.charCodeAt(i).toString(16) + " ";
        }
        gs.info("[CompanyLookup Debug] Raw AI Response: >>>" + raw_AI_response + "<<<");
        gs.info("[CompanyLookup Debug] AI Response Hex Trace: " + hexDump);
    }

    var tagIndex = raw_AI_response ? raw_AI_response.indexOf("MATCHED_NAME:") : -1;
    gs.info("[CompanyLookup Debug] Check: 'indexOf MATCHED_NAME:' -> Position " + tagIndex);

    var validated_AI_match = "";
    var aiSuggestedName = "";

    if (tagIndex > -1) {
        aiSuggestedName = raw_AI_response.split("MATCHED_NAME:")[1].trim().replace(/^["']|["']$/g, '');
        gs.info("[CompanyLookup Debug] Extracted AI Name: >>>" + aiSuggestedName + "<<<");
    } else {
        aiSuggestedName = (raw_AI_response || "").trim();
        gs.info("[CompanyLookup Debug] No Tag. Using Raw AI Trimmed: >>>" + aiSuggestedName + "<<<");
    }

    if (aiSuggestedName) {
        validated_AI_match = helper.findCompanyByCode(aiSuggestedName);
        gs.info("[CompanyLookup Debug] Validating AI Suggestion against DB -> Result: >>>" + validated_AI_match + "<<<");
    }

    // --- STEP 3: COMPARISON & FINAL DECISION ---
    outputs.matched_name = result_by_code;
    outputs.matched_name_ai = validated_AI_match || "No valid AI match";

    var codeMatch = (result_by_code || "").toLowerCase().trim();
    var aiMatch = (validated_AI_match || "").toLowerCase().trim();

    var doNamesMatch = (codeMatch !== "" && aiMatch !== "" && codeMatch === aiMatch);
    gs.info("[CompanyLookup Debug] Final Comparison: ['" + codeMatch + "' === '" + aiMatch + "'] -> " + doNamesMatch);

    if (doNamesMatch) {
        outputs.name_agreed = true;
        outputs.definitive_name = result_by_code;

        // --- ALIAS UPDATE ---
        var updateGr = new GlideRecord('core_company');
        updateGr.addActiveQuery();
        updateGr.addQuery('name', result_by_code);
        updateGr.query();

        if (updateGr.next()) {
            var currentAliases = updateGr.getValue('u_alias') || "";
            var isDuplicate = currentAliases.toLowerCase().indexOf(inputName.toLowerCase()) > -1;
            
            gs.info("[CompanyLookup Debug] Alias Check: '" + inputName + "' in '" + currentAliases + "' -> Duplicate? " + isDuplicate);

            if (!isDuplicate) {
                var newList = currentAliases ? currentAliases + "," + inputName : inputName;
                updateGr.setValue('u_alias', newList);
                updateGr.update();
                gs.info("[CompanyLookup Debug] Updated record with new alias.");
            }
        }
    } else {
        gs.info("[CompanyLookup Debug] Conditions for 'name_agreed' not met. Clearing definitive_name.");
        outputs.name_agreed = false;
        outputs.definitive_name = "";
    }
    
    gs.info("[CompanyLookup Debug] --- END TRACE ---");

})(inputs, outputs);

